SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS companies(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,legal_name VARCHAR(200),phone VARCHAR(30),email VARCHAR(160),address TEXT,tax_number VARCHAR(80),currency CHAR(3) NOT NULL DEFAULT 'IQD',logo_url TEXT,invoice_prefix VARCHAR(20) DEFAULT 'INV',quotation_prefix VARCHAR(20) DEFAULT 'QT',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS branches(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,phone VARCHAR(30),address TEXT,is_active BOOLEAN DEFAULT TRUE,FOREIGN KEY(company_id) REFERENCES companies(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS roles(id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,name_ar VARCHAR(80) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED,role_id SMALLINT UNSIGNED NOT NULL,name VARCHAR(140) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,phone VARCHAR(30),password_hash VARCHAR(255) NOT NULL,is_active BOOLEAN DEFAULT TRUE,last_login_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS manufacturers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,country VARCHAR(80),phone VARCHAR(30),email VARCHAR(160),website VARCHAR(255),notes TEXT,is_active BOOLEAN DEFAULT TRUE,UNIQUE(company_id,name),FOREIGN KEY(company_id) REFERENCES companies(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS brands(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,manufacturer_id BIGINT UNSIGNED,name VARCHAR(160) NOT NULL,logo_url TEXT,description TEXT,is_active BOOLEAN DEFAULT TRUE,UNIQUE(company_id,name),FOREIGN KEY(company_id) REFERENCES companies(id),FOREIGN KEY(manufacturer_id) REFERENCES manufacturers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,parent_id BIGINT UNSIGNED,name VARCHAR(120) NOT NULL,is_active BOOLEAN DEFAULT TRUE,FOREIGN KEY(company_id) REFERENCES companies(id),FOREIGN KEY(parent_id) REFERENCES categories(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED,category_id BIGINT UNSIGNED,name VARCHAR(180) NOT NULL,description TEXT,main_image_url TEXT,unit VARCHAR(40) DEFAULT 'قطعة',is_gift_eligible BOOLEAN DEFAULT FALSE,is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(company_id,name),FOREIGN KEY(company_id) REFERENCES companies(id),FOREIGN KEY(brand_id) REFERENCES brands(id),FOREIGN KEY(category_id) REFERENCES categories(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_variants(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,sku VARCHAR(80) NOT NULL UNIQUE,barcode VARCHAR(100),variant_name VARCHAR(160) NOT NULL,color_name VARCHAR(80),color_hex VARCHAR(12),size_value VARCHAR(80),attributes JSON,image_url TEXT,cost_price DECIMAL(15,3) NOT NULL DEFAULT 0,wholesale_price DECIMAL(15,3) NOT NULL DEFAULT 0,retail_price DECIMAL(15,3) NOT NULL DEFAULT 0,mandatory_price DECIMAL(15,3) NOT NULL DEFAULT 0,minimum_sale_price DECIMAL(15,3) NOT NULL DEFAULT 0,reorder_level DECIMAL(15,3) DEFAULT 0,is_gift_eligible BOOLEAN DEFAULT FALSE,is_active BOOLEAN DEFAULT TRUE,FOREIGN KEY(product_id) REFERENCES products(id),INDEX(barcode)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS warehouses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED,name VARCHAR(120) NOT NULL,address TEXT,is_active BOOLEAN DEFAULT TRUE,FOREIGN KEY(company_id) REFERENCES companies(id),FOREIGN KEY(branch_id) REFERENCES branches(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS inventory_balances(warehouse_id BIGINT UNSIGNED NOT NULL,variant_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(15,3) NOT NULL DEFAULT 0,reserved_quantity DECIMAL(15,3) NOT NULL DEFAULT 0,average_cost DECIMAL(15,3) NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(warehouse_id,variant_id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),FOREIGN KEY(variant_id) REFERENCES product_variants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS inventory_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,warehouse_id BIGINT UNSIGNED NOT NULL,variant_id BIGINT UNSIGNED NOT NULL,movement_type ENUM('OPENING','PURCHASE','SALE','SALE_GIFT','RETURN_IN','RETURN_OUT','TRANSFER_IN','TRANSFER_OUT','ADJUSTMENT') NOT NULL,quantity DECIMAL(15,3) NOT NULL,unit_cost DECIMAL(15,3) DEFAULT 0,reference_type VARCHAR(40),reference_id BIGINT UNSIGNED,notes TEXT,created_by BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(company_id,created_at),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),FOREIGN KEY(variant_id) REFERENCES product_variants(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS customers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,shop_name VARCHAR(180),phone VARCHAR(30) NOT NULL,alternate_phone VARCHAR(30),governorate VARCHAR(80),area VARCHAR(100),address TEXT,location_url TEXT,credit_limit DECIMAL(15,3) DEFAULT 0,opening_balance DECIMAL(15,3) DEFAULT 0,notes TEXT,is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(company_id,phone),FOREIGN KEY(company_id) REFERENCES companies(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sales_reps(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,commission_type ENUM('NONE','PERCENT','FIXED') DEFAULT 'NONE',commission_value DECIMAL(15,3) DEFAULT 0,can_sell_all_products BOOLEAN DEFAULT TRUE,credit_limit DECIMAL(15,3) DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sales_rep_products(rep_id BIGINT UNSIGNED NOT NULL,variant_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(rep_id,variant_id),FOREIGN KEY(rep_id) REFERENCES sales_reps(id),FOREIGN KEY(variant_id) REFERENCES product_variants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS quotations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED,customer_id BIGINT UNSIGNED,quotation_no VARCHAR(60) NOT NULL,status ENUM('DRAFT','SENT','ACCEPTED','REJECTED','EXPIRED','CONVERTED') DEFAULT 'DRAFT',valid_until DATE,subtotal DECIMAL(15,3) NOT NULL DEFAULT 0,discount_amount DECIMAL(15,3) NOT NULL DEFAULT 0,total DECIMAL(15,3) NOT NULL DEFAULT 0,notes TEXT,created_by BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(company_id,quotation_no),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS quotation_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quotation_id BIGINT UNSIGNED NOT NULL,variant_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(15,3) NOT NULL,gift_quantity DECIMAL(15,3) DEFAULT 0,unit_price DECIMAL(15,3) NOT NULL,discount_amount DECIMAL(15,3) DEFAULT 0,line_total DECIMAL(15,3) NOT NULL,FOREIGN KEY(quotation_id) REFERENCES quotations(id) ON DELETE CASCADE,FOREIGN KEY(variant_id) REFERENCES product_variants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS invoices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED,warehouse_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,sales_rep_id BIGINT UNSIGNED,invoice_no VARCHAR(60) NOT NULL,status ENUM('DRAFT','CONFIRMED','PARTIALLY_PAID','PAID','CANCELLED','RETURNED') DEFAULT 'DRAFT',payment_type ENUM('CASH','INSTALLMENT') NOT NULL,invoice_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,subtotal DECIMAL(15,3) NOT NULL DEFAULT 0,discount_amount DECIMAL(15,3) NOT NULL DEFAULT 0,total DECIMAL(15,3) NOT NULL DEFAULT 0,paid_amount DECIMAL(15,3) NOT NULL DEFAULT 0,balance_amount DECIMAL(15,3) NOT NULL DEFAULT 0,notes TEXT,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(company_id,invoice_no),INDEX(company_id,invoice_date),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(sales_rep_id) REFERENCES sales_reps(id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS invoice_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,variant_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(15,3) NOT NULL,gift_quantity DECIMAL(15,3) DEFAULT 0,unit_cost DECIMAL(15,3) NOT NULL,unit_price DECIMAL(15,3) NOT NULL,discount_amount DECIMAL(15,3) DEFAULT 0,line_total DECIMAL(15,3) NOT NULL,FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE,FOREIGN KEY(variant_id) REFERENCES product_variants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,invoice_id BIGINT UNSIGNED,customer_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(15,3) NOT NULL,payment_method ENUM('CASH','BANK','CARD','WALLET','OTHER') DEFAULT 'CASH',reference_no VARCHAR(100),payment_date DATETIME DEFAULT CURRENT_TIMESTAMP,notes TEXT,received_by BIGINT UNSIGNED NOT NULL,FOREIGN KEY(invoice_id) REFERENCES invoices(id),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(received_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS installments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,installment_no INT NOT NULL,due_date DATE NOT NULL,amount DECIMAL(15,3) NOT NULL,paid_amount DECIMAL(15,3) DEFAULT 0,status ENUM('PENDING','PARTIAL','PAID','OVERDUE') DEFAULT 'PENDING',paid_at DATETIME,UNIQUE(invoice_id,installment_no),FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED,user_id BIGINT UNSIGNED,action VARCHAR(80) NOT NULL,entity_type VARCHAR(60),entity_id BIGINT UNSIGNED,old_data JSON,new_data JSON,ip_address VARCHAR(64),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(company_id,created_at),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
